-- ========================================================


-- 并不在 BundleResources 目录下, 此资源不会进包
local debugBox_imgui_path = "Assets/LevelPrototype/2D_Art/Prefab/debugBox_IMGUI.prefab"



-- ========================================================

function DebugBox_IMGUI_Loader:__init()
    self.controller = nil
    self.debugBox_imgui = nil
    self.isInit = false
end


function DebugBox_IMGUI_Loader:__delete()
    if self.co_1 ~= nil then
        cs_coroutine.stop(self.co_1)
    end
    self.co_1 = nil
end


function DebugBox_IMGUI_Loader:Awake()
end



function DebugBox_IMGUI_Loader:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:
    if DreamSpaceLuaUtils.IsEditorPlatform() == false then
        return
    end

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(self.DelayInit, self)
end


function DebugBox_IMGUI_Loader:DelayInit()

    if CS.System.IO.File.Exists(debugBox_imgui_path) == false then 
        print("koko - debugBox imgui: 未能找到 path 内文件: " .. tostring(debugBox_imgui_path) )
        return
    end

    -- editor 模式下的 同步加载:
    local prefab = CS.UnityEditor.AssetDatabase.LoadAssetAtPath(debugBox_imgui_path, typeof(GameObject) )
    if isNull(prefab) then 
        print("koko - debugBox imgui: prefab 加载失败")
    else 
        self.debugBox_imgui = GameObject.Instantiate(prefab)
        KTool.SetActive( self.debugBox_imgui, false )

        self.boxLuaEnv = DreamSpaceLuaUtils.GetLuaScr(self.debugBox_imgui, "Game.DreamSpace.DebugBox.DebugBox_IMGUI_Lua" )
        if isNull(self.boxLuaEnv) then 
            printError("koko - prefab 中未找到 DebugBox_IMGUI_Lua lua 脚本")
            return
        end
    end 

    self.isInit = true
    print("koko - debugBox imgui loader 初始化完成")
end



function DebugBox_IMGUI_Loader:OnDestroy()

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end





-- =========================================== Self ================================================ --


function DebugBox_IMGUI_Loader:Update()

    if  Input.GetKeyDown(KeyCode.F12) then 
        if DreamSpaceLuaUtils.IsEditorPlatform() == false then 
            print("koko - 不在 Editor 平台, 无法启动 debugBox")
            return
        end 
        if isNull(self.debugBox_imgui) then 
            print("koko - debugBox IMGUI prefab 加载失败, 无法启动 debugBox")
            return
        end 
        if self.isInit == false then 
            print("koko - init 失败, 无法启动 debugBox")
            return
        end 
        --
        KTool.SetActive( self.debugBox_imgui, not self.debugBox_imgui.activeSelf )

        
        if self.debugBox_imgui.activeSelf then 
            self.boxLuaEnv:WhenBoxShow();
        else
            self.boxLuaEnv:WhenBoxHide();
        end
        
    end
end




return DebugBox_IMGUI_Loader

